// === Tab: mySketch ===
/**
 * Animation Principles 1-12: The Grand 3D Neon Stage
 * Features: 12 Objects, 3D Arcs, Velocity-Aligned Stretching, and Top-Point Attachment.
 */

let balls = [];
let numBalls = 12;
let groundY;

function setup() {
  // 11. Solid Drawing: Enable WEBGL for 3D depth and volume
  createCanvas(windowWidth, windowHeight, WEBGL);

  // 12. Appeal: Use HSB for vivid and intuitive color control
  colorMode(HSB, 360, 100, 100, 100);

  // Define ground level in WEBGL coordinate space
  groundY = height / 6;

  // Initialize 12 independent animated entities
  for (let i = 0; i < numBalls; i++) {
    balls.push(new AnimatedBall(i));
  }
}

function draw() {
  // Deep space background for neon contrast
  background(260, 80, 5); 

  // 3. Staging & 11. Solid Drawing: Set up dynamic lighting
  setupLights();

  // Render the 3D environment
  drawFloor();

  // Update and render each ball
  for (let ball of balls) {
    ball.update();
    ball.display();
  }
}

function setupLights() {
  ambientLight(260, 20, 10);
  // High-contrast point lights to emphasize 3D forms
  pointLight(0, 0, 100, 0, -1000, 500); 
  pointLight(200, 100, 100, -width, -200, 200); 
  pointLight(330, 100, 100, width, -200, 200);
}

function drawFloor() {
  push();
  translate(0, groundY + 5, 0);
  rotateX(HALF_PI);
  ambientMaterial(260, 50, 10);
  noStroke();
  plane(width * 4, 4000);

  // Render neon grid for spatial reference
  strokeWeight(1);
  for (let x = -width * 2; x <= width * 2; x += 200) {
    stroke(200, 80, 40, 20);
    line(x, -2000, x, 2000);
  }
  pop();
}

class AnimatedBall {
  constructor(id) {
    this.id = id;
    this.radius = random(30, 50);

    // Initial color settings
    this.hue = random(360);
    this.targetHue = this.hue;
    this.bright = 100;

    // 3D Position and Velocity
    this.ballX = random(-width/3, width/3);
    this.ballZ = random(-800, 100);
    this.ballY = groundY - this.radius;
    this.velocity = createVector(0, 0, 0);

    // 5. Follow Through: Initialize secondary object
    this.fPos = createVector(this.ballX, this.ballY, this.ballZ);
    this.fVel = createVector(0, 0, 0);

    this.state = "IDLE";
    this.timer = floor(random(100)); // Randomize start timing
    this.rings = [];

    // Scale factors for Squash and Stretch
    this.curW = 1.0; this.curH = 1.0;
    this.targetW = 1.0; this.targetH = 1.0;
  }

  update() {
    // 12. Appeal: Smooth color transition
    this.hue = lerp(this.hue, this.targetHue, 0.05);

    this.updateStateLogic();

    // 4. Straight Ahead / Pose to Pose: Interpolate shapes
    this.curW = lerp(this.curW, this.targetW, 0.2);
    this.curH = lerp(this.curH, this.targetH, 0.2);

    this.updateSecondaryMotion();
  }

  updateStateLogic() {
    if (this.state === "IDLE") {
      this.timer++;
      this.targetW = 1.0; this.targetH = 1.0;
      this.bright = 70;
      this.velocity.set(0, 0, 0);

      if (this.timer > random(40, 100)) {
        this.state = "ANTICIPATION";
        this.timer = 0;
        this.maxJumpH = random(200, 450);
        this.jumpDur = floor(map(this.maxJumpH, 200, 450, 35, 60));
        this.startX = this.ballX; this.startZ = this.ballZ;
        this.targetX = constrain(this.ballX + random(-600, 600), -width/2, width/2);
        this.targetZ = constrain(this.ballZ + random(-800, 800), -1500, 300);
      }
    } 
    else if (this.state === "ANTICIPATION") {
      this.timer++;
      // 2. Anticipation: Exaggerated squash before jump
      this.targetH = 0.25; this.targetW = 1.8;
      this.bright = map(this.timer, 0, 30, 70, 255); // Glow as energy builds up

      if (this.timer > 30) {
        this.state = "JUMPING";
        this.jumpTimer = 0;
        this.targetHue = (this.hue + 120) % 360; // Distinct color shift
      }
    } 
    else if (this.state === "JUMPING") {
      this.jumpTimer++;
      let progress = this.jumpTimer / this.jumpDur;
      let prevPos = createVector(this.ballX, this.ballY, this.ballZ);

      // 7. Arcs & 6. Slow In/Out: 3D parabolic movement with Sin curve
      this.ballX = lerp(this.startX, this.targetX, progress);
      this.ballZ = lerp(this.startZ, this.targetZ, progress);
      this.ballY = (groundY - this.radius) - (sin(progress * PI) * this.maxJumpH);

      // Calculate 3D velocity vector
      this.velocity.set(this.ballX - prevPos.x, this.ballY - prevPos.y, this.ballZ - prevPos.z);

      // 1. Squash & Stretch: Stretch relative to speed
      let speed = this.velocity.mag();
      let stretchAmount = map(speed, 0, 25, 0, 1.8);
      this.targetH = 1.0 + stretchAmount;
      this.targetW = 1.0 / sqrt(this.targetH); // Volume preservation
      this.bright = 100;

      if (progress >= 1.0) {
        this.state = "IMPACT";
        this.timer = 0;
        this.targetHue = random(360);
        // 8. Secondary Action: Visual impact ring
        this.rings.push({x: this.ballX, z: this.ballZ, s: 0, a: 100, h: this.hue});
      }
    } 
    else if (this.state === "IMPACT") {
      this.timer++;
      // 10. Exaggeration: Intense impact squash
      this.targetH = 0.2; this.targetW = 2.4;
      this.bright = 150;
      this.velocity.set(0, 0, 0);

      if (this.timer > 6) {
        this.maxJumpH *= 0.45; // Energy loss
        if (this.maxJumpH < 20) {
          this.state = "IDLE";
          this.timer = 0;
        } else {
          this.state = "JUMPING";
          this.jumpTimer = 0;
          this.startX = this.ballX; this.startZ = this.ballZ;
          this.targetX = this.ballX + (this.targetX - this.startX) * 0.5;
          this.targetZ = this.ballZ + (this.targetZ - this.startZ) * 0.5;
          this.jumpDur *= 0.8;
        }
      }
    }
  }

  updateSecondaryMotion() {
    // Determine the world coordinates of the object's top point
    let topPoint = this.getTopPointInWorld();

    // 5. Follow Through: String and secondary ball logic
    let spring = 0.15;
    this.fVel.x += (topPoint.x - this.fPos.x) * spring;
    this.fVel.y += ((topPoint.y - 40) - this.fPos.y) * spring;
    this.fVel.z += (topPoint.z - this.fPos.z) * spring;

    this.fVel.mult(0.7); // Friction
    this.fPos.add(this.fVel);

    // Update rings
    for (let i = this.rings.length - 1; i >= 0; i--) {
      this.rings[i].s += 15;
      this.rings[i].a -= 4;
      if (this.rings[i].a <= 0) this.rings.splice(i, 1);
    }
  }

  getTopPointInWorld() {
    // Default relative top point
    let localTop = createVector(0, -this.radius * this.curH, 0);

    if (this.state === "JUMPING" && this.velocity.mag() > 0.1) {
      // Calculate rotation based on velocity to align stretching
      let angleZ = atan2(this.velocity.x, -this.velocity.y);
      let angleX = atan2(-this.velocity.z, sqrt(this.velocity.x**2 + this.velocity.y**2));

      // Transform local top point to world space using rotation logic
      let ty = localTop.y * cos(angleX);
      let tz = localTop.y * sin(angleX);
      let fx = -ty * sin(angleZ);
      let fy = ty * cos(angleZ);
      let fz = tz;
      return createVector(this.ballX + fx, this.ballY + fy, this.ballZ + fz);
    }
    return createVector(this.ballX, this.ballY - this.radius * this.curH, this.ballZ);
  }

  display() {
    this.drawShadow();
    this.drawRings();

    // Render string and follower
    let top = this.getTopPointInWorld();
    stroke(this.hue, 80, 100, 50);
    strokeWeight(2);
    line(top.x, top.y, top.z, this.fPos.x, this.fPos.y, this.fPos.z);

    push();
    translate(this.fPos.x, this.fPos.y, this.fPos.z);
    noStroke();
    emissiveMaterial((this.hue + 180) % 360, 100, 100);
    sphere(this.radius * 0.3);
    pop();

    // Render main body
    push();
    translate(this.ballX, this.ballY, this.ballZ);

    // Rotate object so its "up" axis aligns with velocity vector
    if (this.state === "JUMPING" && this.velocity.mag() > 0.1) {
      let angleZ = atan2(this.velocity.x, -this.velocity.y);
      let angleX = atan2(-this.velocity.z, sqrt(this.velocity.x**2 + this.velocity.y**2));
      rotateZ(angleZ);
      rotateX(angleX);
    }

    scale(this.curW, this.curH, this.curW); 
    noStroke();
    specularMaterial(this.hue, 90, this.bright);
    emissiveMaterial(this.hue, 100, this.bright * 0.2);
    shininess(50);
    sphere(this.radius);

    // Render eyes
    fill(0, 0, 100);
    let eyeScale = (this.state === "ANTICIPATION" ? 0.2 : 1.0);
    push(); translate(-this.radius*0.35, -this.radius*0.2, this.radius*0.85); sphere(this.radius*0.15 * eyeScale); pop();
    push(); translate(this.radius*0.35, -this.radius*0.2, this.radius*0.85); sphere(this.radius*0.15 * eyeScale); pop();
    pop();
  }

  drawShadow() {
    let dist = groundY - (this.ballY + this.radius);
    let alpha = map(dist, 0, 500, 60, 0);
    let size = map(dist, 0, 500, this.radius * 2.5 * this.curW, this.radius * 5);
    push();
    translate(this.ballX, groundY + 2, this.ballZ);
    rotateX(HALF_PI);
    fill(0, 0, 0, alpha);
    noStroke();
    ellipse(0, 0, size, size);
    pop();
  }

  drawRings() {
    push();
    translate(0, groundY + 1, 0);
    rotateX(HALF_PI);
    noFill();
    strokeWeight(5);
    for (let r of this.rings) {
      stroke(r.h, 100, 100, r.a);
      push(); translate(r.x, r.z); ellipse(0, 0, r.s, r.s); pop();
    }
    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  groundY = height / 6;
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

